begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(23);
select is((select count(*)::int from pg_tables where schemaname='public' and rowsecurity and tablename in ('invoices','invoice_items','invoice_receivable_entries','invoice_number_counters')),4,'Invoice tables all enforce RLS');
select ok(not has_table_privilege('authenticated','public.invoices','select'),'Raw monetary invoice rows are not exposed to JS numbers');
select ok(not has_table_privilege('authenticated','public.invoice_receivable_entries','insert'),'Receivables require checked lifecycle RPCs');
create temporary table billing_scope(label text primary key,id uuid);
grant select,insert on billing_scope to authenticated;
insert into auth.users(id,email) values('99999000-0000-0000-0000-000000000001','native-invoice-owner@example.test'),('99999000-0000-0000-0000-000000000002','native-invoice-outsider@example.test');
set local role authenticated;
set local request.jwt.claim.sub='99999000-0000-0000-0000-000000000001';
insert into billing_scope select 'tenant',public.create_business('Native Invoices');
insert into billing_scope select 'branch',id from public.branches limit 1;
insert into billing_scope select 'customer',public.save_customer((select id from billing_scope where label='tenant'),null,'{"first_name":"Invoice contact","phone":"998901234"}',array[(select id from billing_scope where label='branch')]);
insert into billing_scope select 'invoice',public.save_invoice_draft((select id from billing_scope where label='tenant'),null,'99999000-0000-0000-0000-000000000010',0,
 jsonb_build_object('branch_id',(select id from billing_scope where label='branch'),'customer_id',(select id from billing_scope where label='customer'),'issue_date',current_date,'due_date',current_date,'discount_amount','10.00'),
 '[{"description":"Tuition","quantity":"1.5","unit_price":"100.10","discount_amount":"0.15"}]');
select is(public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->>'total','140.00','Line multiplication/rounding/discounts are exact');
select is(public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->>'outstanding','0.00','Draft creates no debt');
select is(public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->'invoice'->>'invoice_number',null::text,'No number allocated to draft');
select lives_ok($$select public.transition_invoice((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'),'99999000-0000-0000-0000-000000000011',1,'issue')$$,'Owner issues invoice');
set constraints all immediate;
select is(public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->'invoice'->>'invoice_number','INV-000001','Business numbering begins on issuance');
select is(public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->>'outstanding','140.00','Issue posts exact debt');
select is(public.transition_invoice((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'),'99999000-0000-0000-0000-000000000011',1,'issue'),(select id from billing_scope where label='invoice'),'Identical issue request is idempotent');
select is((public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->>'audit_total')::int,2,'Repeat does not duplicate audit');
select is(public.debt_directory((select id from billing_scope where label='tenant'))->'summary'->>'outstanding','140.00','Debt directory agrees with document');
reset role;
select throws_ok($$update public.invoice_items set unit_price=1 where invoice_id=(select id from billing_scope where label='invoice')$$,'P0001','Only draft invoice items can change','Issued line values cannot mutate');
select throws_ok($$delete from public.invoice_receivable_entries where invoice_id=(select id from billing_scope where label='invoice')$$,'23514','Posted financial history is immutable','Receivable history is append-only');
select is((select count(*)::int from public.financial_ledger_entries where tenant_id=(select id from billing_scope where label='tenant')),0,'Invoices never move cash');
set local role authenticated;
set local request.jwt.claim.sub='99999000-0000-0000-0000-000000000002';
select throws_ok($$select public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))$$,'42501','Invoice access denied','Other identity cannot read document');
select throws_ok($$select public.transition_invoice((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'),gen_random_uuid(),2,'void','Foreign request')$$,'42501','Invoice command denied','Foreign tenant manipulation is denied');
set local request.jwt.claim.sub='99999000-0000-0000-0000-000000000001';
set constraints all deferred;
select lives_ok($$select public.transition_invoice((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'),'99999000-0000-0000-0000-000000000012',2,'void','Incorrect service')$$,'Authorized void succeeds');
set constraints all immediate;
select is(public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->>'outstanding','0.00','Void offsets full receivable');
select is(public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))->>'total','140.00','Original issued total is retained');
select is(public.customer_financial_profile((select id from billing_scope where label='tenant'),(select id from billing_scope where label='customer'))->'summary'->>'voided_charges','140.00','Customer history includes original void offset');
set local request.jwt.claim.sub='';
select throws_ok($$select public.invoice_details((select id from billing_scope where label='tenant'),(select id from billing_scope where label='invoice'))$$,'42501','Invoice access denied','Subjectless read is denied');
reset role;
select is((select count(*)::int from public.invoice_receivable_entries where tenant_id=(select id from billing_scope where label='tenant')),2,'Exactly one original charge and one offset remain');
select * from finish();
rollback;
